//! The `wire-ts` command: TypeScript declarations for the dashboard wire types and the `PATHS` table of route and browser page paths.

use std::any::TypeId;
use std::collections::{BTreeMap, HashSet};

use ts_rs::{Config, TS, TypeVisitor};

const HEADER: &str = "\
// Generated by `gang-bindings wire-ts` from the types of `gang-wire`; do not edit.
// Fields are lowerCamelCase and unset optionals are absent. Sizes are bytes, timestamps are RFC 3339 strings, durations are `Duration` strings, and enums are UPPER_SNAKE strings that may grow, so a switch over one needs a default arm.

";

const PRELUDE: &str = "\
/** RFC 3339, UTC, millisecond precision: `2026-01-15T10:09:30.000Z`. */
export type Timestamp = string;

/** Seconds with optional fraction and an `s` suffix: `600s`, `0.250s`. */
export type Duration = string;

/** A count of bytes. */
export type Bytes = number;
";

/// Renders the TypeScript declarations of every dashboard wire type.
pub(crate) fn render() -> Result<String, crate::Error> {
    let cfg = Config::new().with_large_int("number");
    let mut out = String::from(HEADER);
    out.push_str(PRELUDE);
    for decl in collect(&cfg).values() {
        out.push('\n');
        out.push_str(&export_decl(decl));
    }
    out.push('\n');
    out.push_str(&paths_decl()?);
    out.push('\n');
    out.push_str(&user_code_decl()?);
    Ok(out)
}

/// Collects the declaration of every root type and every type reachable from them, by name.
fn collect(cfg: &Config) -> BTreeMap<String, String> {
    let mut out = BTreeMap::new();
    let mut seen = HashSet::new();
    walk::<gang_wire::Isa>(cfg, &mut out, &mut seen);
    walk::<gang_wire::Session>(cfg, &mut out, &mut seen);
    walk::<gang_wire::ApproveDeviceAuthorizationRequest>(cfg, &mut out, &mut seen);
    walk::<gang_wire::ApproveDeviceAuthorizationResponse>(cfg, &mut out, &mut seen);
    walk::<gang_wire::DeviceAuthorization>(cfg, &mut out, &mut seen);
    walk::<gang_wire::DeviceAuthorizationState>(cfg, &mut out, &mut seen);
    walk::<gang_wire::ListPrincipalsResponse>(cfg, &mut out, &mut seen);
    walk::<gang_wire::ListRolesResponse>(cfg, &mut out, &mut seen);
    walk::<gang_wire::ListEventsResponse>(cfg, &mut out, &mut seen);
    walk::<gang_wire::State>(cfg, &mut out, &mut seen);
    walk::<gang_wire::Frame>(cfg, &mut out, &mut seen);
    walk::<gang_wire::EventChange>(cfg, &mut out, &mut seen);
    out
}

struct Collector<'a> {
    cfg: &'a Config,
    out: &'a mut BTreeMap<String, String>,
    seen: &'a mut HashSet<TypeId>,
}

impl TypeVisitor for Collector<'_> {
    fn visit<U: TS + 'static + ?Sized>(&mut self) {
        walk::<U>(self.cfg, &mut *self.out, &mut *self.seen);
    }
}

fn walk<T: TS + 'static + ?Sized>(
    cfg: &Config,
    out: &mut BTreeMap<String, String>,
    seen: &mut HashSet<TypeId>,
) {
    if !seen.insert(TypeId::of::<T>()) {
        return;
    }
    if T::output_path().is_some() {
        out.entry(T::ident(cfg)).or_insert_with(|| T::decl(cfg));
    }
    let mut c = Collector { cfg, out, seen };
    T::visit_dependencies(&mut c);
    T::visit_generics(&mut c);
}

/// Prefixes the first `type ` line of a declaration with `export `, keeping any doc block.
fn export_decl(decl: &str) -> String {
    let mut out = String::with_capacity(decl.len() + 8);
    let mut exported = false;
    for line in decl.lines() {
        if !exported && line.starts_with("type ") {
            out.push_str("export ");
            exported = true;
        }
        out.push_str(line);
        out.push('\n');
    }
    out
}

/// Renders the `PATHS` constant: the template of every route in the shared route table, keyed by
/// its `RouteId` variant name in lowerCamelCase, then every server-owned `/ui` route and the error page.
fn paths_decl() -> Result<String, serde_json::Error> {
    let entries: String = gang_wire::routes::ROUTES
        .iter()
        .map(|route| path_entry(&lower_camel(&format!("{:?}", route.id)), route.template))
        .chain(
            gang_wire::UiRoute::ALL
                .iter()
                .map(|route| path_entry(&lower_camel(&format!("{route:?}")), route.path())),
        )
        .chain([
            path_entry("deviceApproved", gang_wire::DEVICE_APPROVED_PATH),
            path_entry("error", gang_wire::ERROR_PATH),
        ])
        .collect::<Result<_, _>>()?;
    Ok(format!("export const PATHS = {{\n{entries}}} as const;\n"))
}

/// Renders the shared user-code alphabet and length for the dashboard.
fn user_code_decl() -> Result<String, serde_json::Error> {
    Ok(format!(
        "/** User codes: `length` characters of `alphabet`, displayed as two halves joined by `-`. */\n\
         export const USER_CODE = {{ alphabet: {}, length: {} }} as const;\n",
        json_string(gang_wire::USER_CODE_ALPHABET)?,
        gang_wire::USER_CODE_LENGTH,
    ))
}

/// Builds one `key: "path",` entry of the `PATHS` constant.
fn path_entry(key: &str, path: &str) -> Result<String, serde_json::Error> {
    Ok(format!("  {key}: {},\n", json_string(path)?))
}

/// Lowers the first character of a variant name, so `GetServer` becomes `getServer`.
fn lower_camel(name: &str) -> String {
    let mut out = String::with_capacity(name.len());
    let mut chars = name.chars();
    if let Some(first) = chars.next() {
        out.extend(first.to_lowercase());
    }
    out.push_str(chars.as_str());
    out
}

/// Quotes `text` as a JSON string, escaping `"`, `\` and control characters, so the result is a
/// valid TypeScript string literal.
fn json_string(text: &str) -> Result<String, serde_json::Error> {
    serde_json::to_string(text)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn output_is_identical_across_calls() {
        assert_eq!(render().unwrap(), render().unwrap());
    }

    #[test]
    fn output_starts_with_the_generated_header() {
        assert!(render().unwrap().starts_with("// Generated by"));
    }

    #[test]
    fn output_exports_the_root_and_nested_types() {
        let rendered = render().unwrap();
        assert!(rendered.contains("export type Session = "), "{rendered}");
        assert!(
            rendered.contains("export type ApproveDeviceAuthorizationRequest = "),
            "{rendered}"
        );
        assert!(
            rendered.contains("export type ApproveDeviceAuthorizationResponse = "),
            "{rendered}"
        );
        assert!(
            rendered.contains("export type DeviceAuthorization = "),
            "{rendered}"
        );
        assert!(
            rendered.contains("export type DeviceAuthorizationState = "),
            "{rendered}"
        );
        assert!(
            rendered.contains("export type ScalingEvent = "),
            "{rendered}"
        );
        assert!(
            rendered.contains("export type Cause = \"DEMAND\" | \"IDLE_TIMEOUT\""),
            "{rendered}"
        );
        assert!(rendered.contains("export type State = "), "{rendered}");
        assert!(rendered.contains("export type Frame = "), "{rendered}");
        assert!(rendered.contains("export type Delta = "), "{rendered}");
    }

    #[test]
    fn output_exports_the_user_code_configuration_after_paths() {
        let rendered = render().unwrap();
        let paths = rendered.find("export const PATHS = ").unwrap();
        let user_code = rendered
            .find("export const USER_CODE = { alphabet: \"BCDFGHJKLMNPQRSTVWXZ\", length: 8 } as const;")
            .unwrap();
        assert!(paths < user_code);
    }

    #[test]
    fn paths_list_every_route_and_the_browser_pages() {
        let rendered = paths_decl().unwrap();
        for line in [
            "  watchState: \"/v1/state:watch\",",
            "  getSession: \"/v1/session\",",
            "  createDeviceAuthorization: \"/v1/deviceAuthorizations\",",
            "  login: \"/ui/login\",",
            "  callback: \"/ui/callback\",",
            "  logout: \"/ui/logout\",",
            "  renew: \"/ui/renew\",",
            "  device: \"/ui/device\",",
            "  deviceApproved: \"/ui/device/approved\",",
            "  error: \"/ui/error\",",
        ] {
            assert!(
                rendered.lines().any(|entry| entry == line),
                "{line}\n{rendered}"
            );
        }
        assert_eq!(
            rendered
                .lines()
                .filter(|line| line.starts_with("  "))
                .count(),
            gang_wire::routes::ROUTES.len() + gang_wire::UiRoute::ALL.len() + 2
        );
    }
}
